  8	import com.shop.model.OrderItem;
  9	import com.shop.model.enums.NotificationType;
 10	import com.shop.model.enums.OrderStatus;
 11	import com.shop.repository.CustomerRepository;
 12	import com.shop.repository.NotificationRepository;
