166	    public Order shipOrder(Long orderId, String trackingCode) {
167	        try (Connection conn = database.getConnection()) {
168	            conn.setAutoCommit(false);
169	            try {
170	                Order order = orderRepository.findByIdForUpdate(conn, orderId);
171	                if (order == null) {
172	                    throw new BusinessException("ORDER_NOT_FOUND", 404);
173	                }
174	
175	                if (order.getStatus() != OrderStatus.PAID) {
176	                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
177	                }
178	
179	                orderRepository.updateStatus(conn, orderId, OrderStatus.SHIPPED);
180	                orderRepository.updateTrackingCode(conn, orderId, trackingCode);
181	
182	                notificationRepository.create(conn, NotificationType.ORDER_SHIPPED, orderId, order.getCustomerCpf());
183	
184	                conn.commit();
185	                return orderRepository.findById(orderId);
186	            } catch (BusinessException e) {
187	                conn.rollback();
188	                throw e;
189	            } catch (Exception e) {
190	                conn.rollback();
191	                throw new RuntimeException("Failed to ship order", e);
192	            }
193	        } catch (SQLException e) {
194	            throw new RuntimeException("Database connection failed", e);
195	        }
196	    }
197	
198	    public Order deliverOrder(Long orderId) {
199	        try (Connection conn = database.getConnection()) {
200	            conn.setAutoCommit(false);
201	            try {
202	                Order order = orderRepository.findByIdForUpdate(conn, orderId);
203	                if (order == null) {
204	                    throw new BusinessException("ORDER_NOT_FOUND", 404);
205	                }
206	
207	                if (order.getStatus() != OrderStatus.SHIPPED) {
208	                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
209	                }
210	
211	                orderRepository.updateStatus(conn, orderId, OrderStatus.DELIVERED);
212	
213	                conn.commit();
214	                return orderRepository.findById(orderId);
215	            } catch (BusinessException e) {
216	                conn.rollback();
217	                throw e;
218	            } catch (Exception e) {
219	                conn.rollback();
220	                throw new RuntimeException("Failed to deliver order", e);
221	            }
222	        } catch (SQLException e) {
223	            throw new RuntimeException("Database connection failed", e);
224	        }
225	    }
226	
227	    public Order cancelOrder(Long orderId) {
228	        try (Connection conn = database.getConnection()) {
229	            conn.setAutoCommit(false);
230	            try {
231	                Order order = orderRepository.findByIdForUpdate(conn, orderId);
232	                if (order == null) {
233	                    throw new BusinessException("ORDER_NOT_FOUND", 404);
234	                }
235	
236	                if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
237	                    throw new BusinessException("OPERATION_NOT_ALLOWED", 409);
238	                }
239	
240	                if (order.getStatus() == OrderStatus.CANCELLED) {
241	                    conn.commit();
242	                    return order;
243	                }
244	
245	                if (order.getStatus() == OrderStatus.PAID) {
246	                    for (OrderItem item : order.getItems()) {
247	                        productRepository.incrementStock(conn, item.getSku(), item.getQuantity());
248	                    }
249	
250	                    if (order.getSummary().getNextPurchaseCredit().compareTo(java.math.BigDecimal.ZERO) > 0) {
251	                        customerRepository.subtractCredit(conn, order.getCustomerCpf(),
252	                                order.getSummary().getNextPurchaseCredit());
253	                    }
254	                }
255	
256	                orderRepository.updateStatus(conn, orderId, OrderStatus.CANCELLED);
257	                notificationRepository.create(conn, NotificationType.ORDER_CANCELLED, orderId, order.getCustomerCpf());
258	
259	                conn.commit();
260	                return orderRepository.findById(orderId);
261	            } catch (BusinessException e) {
262	                conn.rollback();
263	                throw e;
264	            } catch (Exception e) {
265	                conn.rollback();
266	                throw new RuntimeException("Failed to cancel order", e);
267	            }
268	        } catch (SQLException e) {
269	            throw new RuntimeException("Database connection failed", e);
270	        }
271	    }
272	
273	    public Order getOrder(Long orderId) {
274	        Order order = orderRepository.findById(orderId);
275	        if (order == null) {
276	            throw new BusinessException("ORDER_NOT_FOUND", 404);
277	        }
278	        return order;
279	    }
280	}
