283	import com.shop.model.enums.CouponCode;
284	import com.shop.model.enums.PaymentMethod;
285	
286	import java.math.BigDecimal;
287	import java.math.RoundingMode;
288	
289	public class PaymentService {
290	
291	    public static class PaymentCalculation {
292	        public BigDecimal adjustment;
293	        public BigDecimal finalTotal;
294	        public int installments;
295	        public BigDecimal installmentAmount;
296	
297	        public PaymentCalculation(BigDecimal adjustment, BigDecimal finalTotal,
298	                                 int installments, BigDecimal installmentAmount) {
299	            this.adjustment = adjustment;
300	            this.finalTotal = finalTotal;
301	            this.installments = installments;
302	            this.installmentAmount = installmentAmount;
303	        }
304	    }
305	
306	    public PaymentCalculation calculatePayment(PaymentMethod method, BigDecimal orderTotal,
307	                                              int installments, CouponCode coupon,
308	                                              BigDecimal couponDiscount) {
309	        return switch (method) {
310	            case PIX -> calculatePix(orderTotal, coupon, couponDiscount);
311	            case BANK_SLIP -> calculateBankSlip(orderTotal);
312	            case CREDIT_CARD -> calculateCreditCard(orderTotal, installments);
313	        };
314	    }
315	
316	    private PaymentCalculation calculatePix(BigDecimal orderTotal, CouponCode coupon, BigDecimal couponDiscount) {
317	        if (coupon != null && couponDiscount.compareTo(BigDecimal.ZERO) > 0) {
318	            return new PaymentCalculation(BigDecimal.ZERO, orderTotal, 1, orderTotal);
319	        }
320	
321	        BigDecimal discount = orderTotal.multiply(new BigDecimal("0.05"))
322	                .setScale(2, RoundingMode.HALF_EVEN);
323	        BigDecimal finalTotal = orderTotal.subtract(discount);
324	
325	        return new PaymentCalculation(discount.negate(), finalTotal, 1, finalTotal);
326	    }
327	
328	    private PaymentCalculation calculateBankSlip(BigDecimal orderTotal) {
329	        BigDecimal fee = new BigDecimal("3.49");
330	        BigDecimal finalTotal = orderTotal.add(fee);
331	
332	        return new PaymentCalculation(fee, finalTotal, 1, finalTotal);
333	    }
334	
335	    private PaymentCalculation calculateCreditCard(BigDecimal orderTotal, int installments) {
336	        if (installments <= 3) {
337	            BigDecimal installmentAmount = orderTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
338	            return new PaymentCalculation(BigDecimal.ZERO, orderTotal, installments, installmentAmount);
339	        }
340	
341	        BigDecimal monthlyRate = new BigDecimal("0.0199");
342	        BigDecimal onePlusRate = BigDecimal.ONE.add(monthlyRate);
343	        BigDecimal denominator = BigDecimal.ONE.subtract(
344	                onePlusRate.pow(-installments)
345	        );
346	
347	        BigDecimal installmentAmount = orderTotal.multiply(monthlyRate)
348	                .divide(denominator, 2, RoundingMode.HALF_EVEN);
349	
350	        BigDecimal finalTotal = installmentAmount.multiply(new BigDecimal(installments));
351	        BigDecimal adjustment = finalTotal.subtract(orderTotal);
352	
353	        return new PaymentCalculation(adjustment, finalTotal, installments, installmentAmount);
354	    }
355	}

